import React, { useState } from 'react';
import * as XLSX from 'xlsx';

const TelegramUpload = () => {
  // ==========================================
  // STATE MANAGEMENT
  // ==========================================
  const [inputText, setInputText] = useState('');
  const [outputText, setOutputText] = useState('');
  const [categoryName, setCategoryName] = useState('');
  const [prefixCaption, setPrefixCaption] = useState('NONE');
  const [parsedRows, setParsedRows] = useState([]);
  const [copied, setCopied] = useState(false);

  // ==========================================
  // HELPER & PARSER FUNCTIONS
  // ==========================================

  // Parser & Formatter Excel/Teks ke Format Telegram
  const parseAndFormatData = (dataRows, title, prefixType) => {
    let header = '';

    if (prefixType === 'TURUN') {
      header = `INFO: TURUN HARGA\n\n`;
    } else if (prefixType === 'NAIK') {
      header = `INFO: NAIK HARGA\n\n`;
    }

    let result = `${header}${title}\n════════════════════\n\n`;

    const normalizedRows = [];

    dataRows.forEach((row) => {
      let code =
        row.SKU ||
        row['Buyer SKU Code'] ||
        row.Kode ||
        row['Kode Produk'] ||
        row.code ||
        row[0] ||
        '';
      let price =
        row.Harga ||
        row['Harga Jual'] ||
        row['Harga Baru'] ||
        row.price ||
        row[1] ||
        '';

      if (code && price) {
        code = String(code).trim().toUpperCase();

        let numPrice = Number(String(price).replace(/[^0-9]/g, ''));
        let formattedPrice = isNaN(numPrice)
          ? price
          : numPrice.toLocaleString('id-ID');

        let paddedCode = code.padEnd(8, ' ');
        let paddedPrice = String(formattedPrice).padStart(8, ' ');

        result += `${paddedCode} ${paddedPrice}\n`;

        normalizedRows.push({
          sku: code,
          price: isNaN(numPrice) ? price : numPrice,
        });
      }
    });

    setParsedRows(normalizedRows);
    return result;
  };

  // Helper Re-generate Data saat Opsi Header/Judul Berubah
  const handleGenerate = (currentInputText = inputText) => {
    if (!currentInputText.trim()) return;
    const lines = currentInputText.split('\n');
    const rows = lines.map((line) => {
      const parts = line.trim().split(/\s+/);
      return { Kode: parts[0], Harga: parts[1] };
    });

    const formatted = parseAndFormatData(rows, categoryName, prefixCaption);
    setOutputText(formatted);
  };

  // ==========================================
  // EVENT HANDLERS
  // ==========================================

  // Process File Excel Upload
  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json(ws);

      const formatted = parseAndFormatData(data, categoryName, prefixCaption);
      setOutputText(formatted);
    };
    reader.readAsBinaryString(file);
  };

  // Process Text Manual Input
  const handleTextFormat = () => {
    handleGenerate(inputText);
  };

  // Copy Result to Clipboard with Toast Notification
  const handleCopy = () => {
    if (!outputText) return;
    navigator.clipboard.writeText(outputText);
    setCopied(true);
    setTimeout(() => {
      setCopied(false);
    }, 2000);
  };

  // Function Download Template Excel Update Harga Digiflazz
  const handleDownloadDigiflazzTemplate = () => {
    const templateHeader = [['Buyer SKU Code', 'Harga Baru / Margin']];

    const templateData = parsedRows.map((item) => [item.sku, item.price]);
    const fullData = [...templateHeader, ...templateData];

    const ws = XLSX.utils.aoa_to_sheet(fullData);
    ws['!cols'] = [{ wch: 25 }, { wch: 20 }];

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Update Harga Digiflazz');

    const fileName = `Template_Update_Harga_Digiflazz_${
      categoryName.replace(/\s+/g, '_') || 'Produk'
    }.xlsx`;
    XLSX.writeFile(wb, fileName);
  };

  // ==========================================
  // RENDER UI
  // ==========================================
  return (
    <div className="max-w-5xl mx-auto p-4 sm:p-6 space-y-6 font-sans relative text-slate-800 transition-all duration-300">
      {/* Toast Notification */}
      {copied && (
        <div className="fixed bottom-6 right-6 bg-emerald-600 text-white font-semibold text-xs px-4 py-3 rounded-xl shadow-2xl flex items-center gap-2.5 animate-bounce z-50 border border-emerald-500 backdrop-blur-md">
          <svg
            className="w-4 h-4 text-white"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="2.5"
              d="M5 13l4 4L19 7"
            />
          </svg>
          <span>Berhasil disalin ke clipboard!</span>
        </div>
      )}

      <div className="bg-white rounded-2xl border border-slate-200/80 shadow-md hover:shadow-lg transition-all duration-300 overflow-hidden">
        {/* Header Section */}
        <div className="p-5 sm:p-6 border-b border-slate-100 bg-gradient-to-r from-slate-50 via-white to-slate-50 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div className="space-y-1">
            <h2 className="text-base sm:text-lg font-bold text-slate-900 flex items-center gap-2.5">
              <span className="p-2 bg-indigo-50 rounded-lg text-indigo-600 border border-indigo-100/60 shadow-sm">
                <svg
                  className="w-5 h-5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2"
                    d="M11 5.882V19.24a1.76 1.76 0 01-3.417.592l-2.147-6.15M18 13a3 3 0 100-6M5.436 13.683A4.001 4.001 0 017 6h18"
                  />
                </svg>
              </span>
              Template Harga Digiflazz
            </h2>
            <p className="text-xs text-slate-500 pl-0.5">
              Kelola dan format daftar harga produk untuk postingan Telegram dan
              template Digiflazz.
            </p>
          </div>

          <button
            onClick={handleDownloadDigiflazzTemplate}
            className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold px-4 py-2.5 rounded-xl flex items-center gap-2 transition-all duration-200 shadow-sm hover:shadow active:scale-95 shrink-0 group"
            title="Download Template Excel Digiflazz beserta harga terupdate"
          >
            <svg
              className="w-4 h-4 transform group-hover:-translate-y-0.5 transition-transform"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
              />
            </svg>
            <span>Download Template Digiflazz</span>
          </button>
        </div>

        {/* Form Controls Section */}
        <div className="p-5 sm:p-6 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            {/* Input Judul Kategori */}
            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                Judul Kategori / Banner
              </label>
              <input
                type="text"
                value={categoryName}
                onChange={(e) => setCategoryName(e.target.value.toUpperCase())}
                className="w-full bg-slate-50 border border-slate-300/80 rounded-xl px-3.5 py-2.5 text-xs font-bold text-slate-800 outline-none focus:bg-white focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 transition-all shadow-sm"
                placeholder="Silakan masukkan judul"
              />
            </div>

            {/* Select Caption Opsional */}
            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                Caption Tambahan Opsional
              </label>
              <select
                value={prefixCaption}
                onChange={(e) => setPrefixCaption(e.target.value)}
                className="w-full bg-slate-50 border border-slate-300/80 rounded-xl px-3.5 py-2.5 text-xs font-bold text-slate-800 outline-none focus:bg-white focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 transition-all cursor-pointer shadow-sm"
              >
                <option value="NONE">-- Tanpa Caption Tambahan --</option>
                <option value="TURUN">INFO: TURUN HARGA</option>
                <option value="NAIK">INFO: NAIK HARGA</option>
              </select>
            </div>

            {/* Upload File Excel */}
            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                Upload File Excel Produk
              </label>
              <input
                type="file"
                accept=".xlsx, .xls, .csv"
                onChange={handleFileUpload}
                className="w-full text-xs text-slate-500 file:mr-3 file:py-2 file:px-3.5 file:rounded-xl file:border-0 file:text-xs file:font-semibold file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100 cursor-pointer border border-slate-300/80 rounded-xl bg-slate-50 focus:bg-white transition-all shadow-sm"
              />
            </div>
          </div>

          {/* Main Content Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-2">
            {/* Input Section */}
            <div className="flex flex-col space-y-2">
              <label className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                Atau Paste Data Teks (Kode Harga)
              </label>
              <textarea
                rows="14"
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                placeholder=""
                className="w-full bg-slate-50 border border-slate-300/80 rounded-xl p-3.5 text-xs font-mono outline-none focus:bg-white focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 transition-all resize-none shadow-sm"
              ></textarea>
              <button
                onClick={handleTextFormat}
                className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-xs py-2.5 rounded-xl transition-all duration-200 shadow-sm hover:shadow active:scale-95 flex items-center justify-center gap-2 group"
              >
                <svg
                  className="w-4 h-4 text-indigo-200 group-hover:scale-110 transition-transform"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2"
                    d="M13 10V3L4 14h7v7l9-11h-7z"
                  />
                </svg>
                <span>Generate Format Teks</span>
              </button>
            </div>

            {/* Output Section */}
            <div className="flex flex-col space-y-2">
              <div className="flex justify-between items-center h-6">
                <label className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                  Preview Output Telegram
                </label>
                {outputText && (
                  <button
                    onClick={handleCopy}
                    className={`text-xs font-bold px-3 py-1 rounded-lg transition-all duration-200 flex items-center gap-1.5 shadow-sm active:scale-95 ${
                      copied
                        ? 'bg-emerald-600 text-white'
                        : 'bg-emerald-50 text-emerald-600 border border-emerald-200 hover:bg-emerald-100'
                    }`}
                  >
                    {copied ? (
                      <>
                        <svg
                          className="w-3.5 h-3.5"
                          fill="none"
                          stroke="currentColor"
                          viewBox="0 0 24 24"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth="2.5"
                            d="M5 13l4 4L19 7"
                          />
                        </svg>
                        <span>Tersalin</span>
                      </>
                    ) : (
                      <>
                        <svg
                          className="w-3.5 h-3.5"
                          fill="none"
                          stroke="currentColor"
                          viewBox="0 0 24 24"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth="2"
                            d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3"
                          />
                        </svg>
                        <span>Salin Hasil</span>
                      </>
                    )}
                  </button>
                )}
              </div>

              <div className="relative w-full h-[330px] bg-slate-900 rounded-xl p-4 border border-slate-800/80 overflow-hidden flex flex-col shadow-inner group">
                <div className="w-full h-full overflow-y-auto pr-1 custom-scrollbar">
                  <pre className="text-emerald-400 font-mono text-xs whitespace-pre-wrap leading-relaxed select-all selection:bg-emerald-900/60 selection:text-emerald-200">
                    {outputText || (
                      <span className="text-slate-500 italic">
                        Hasil format Telegram akan muncul di sini...
                      </span>
                    )}
                  </pre>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TelegramUpload;