import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { 
  Search as SearchIcon, 
  FileSpreadsheet, 
  Trash2,
  Calendar,
  AlertTriangle,
  Copy,
  ChevronDown,
  RotateCcw,
  TrendingDown,
  HelpCircle,
  CheckCircle2,
  Loader2,
  Inbox
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  collection, 
  onSnapshot, 
  query, 
  where, 
  writeBatch, 
  getDocs, 
  Timestamp 
} from 'firebase/firestore';

// Inisialisasi Firebase
const firebaseConfig = {
  apiKey: process.env.REACT_APP_FIREBASE_KEY,
  authDomain: process.env.REACT_APP_FIREBASE_DOMAIN,
  projectId: process.env.REACT_APP_FIREBASE_PROJECT_ID,
  storageBucket: process.env.REACT_APP_FIREBASE_STORAGE,
  messagingSenderId: process.env.REACT_APP_FIREBASE_SENDER,
  appId: process.env.REACT_APP_FIREBASE_APP_ID
};
const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

// Konfigurasi Telegram
const TELEGRAM_BOT_TOKEN = "8571888481:AAGdqdiaa4kPd_YWqfZauELZ1-ACiMV0iYg";
const TELEGRAM_CHAT_ID = "-1003574594574";

const LogSpeedPanel = () => {
  const [dbData, setDbData] = useState([]);
  const [manualData, setManualData] = useState([]);
  const [isManualUpload, setIsManualUpload] = useState(false);
  const [fileName, setFileName] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('ALL');
  const [dateFilter, setDateFilter] = useState('');
  const [isAutoFit, setIsAutoFit] = useState(false);
  const fileInputRef = useRef(null);

  const [useCustomUploadDate, setUseCustomUploadDate] = useState(false);
  const [customUploadDate, setCustomUploadDate] = useState('');
  const [filterNaOnly, setFilterNaOnly] = useState(false);

  // State Performa: Loading & Error
  const [isLoading, setIsLoading] = useState(true);
  const [errorMessage, setErrorMessage] = useState('');

  // Set pelacak ID transaksi minus yang sudah pernah dikirimkan notifikasinya
  const notifiedTrxKeysRef = useRef(new Set());

  // Default Lebar Kolom
  const defaultWidths = useMemo(() => ({
    tglEntri: 130, 
    tglStatus: 130, 
    produk: 75,
    tujuan: 115, 
    sn: 160, 
    status: 70,
    hargaJual: 85,
    hargaBeli: 85,
    laba: 75,
    supplier: 95,
    jawabanProvider: 230
  }), []);

  const [columnWidths, setColumnWidths] = useState(defaultWidths);
  const resizingColumn = useRef(null);
  const startX = useRef(0);
  const startWidth = useRef(0);

  // Helper String Tanggal YYYY-MM-DD
  const getTodayString = useCallback(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }, []);

  const formatRupiah = useCallback((val) => {
    const num = Number(val);
    if (isNaN(num)) return val ? String(val) : "0";
    return num.toLocaleString('id-ID');
  }, []);

  // Notifikasi Telegram
  const sendTelegramNotification = useCallback(async (text) => {
    const botToken = TELEGRAM_BOT_TOKEN || process.env.REACT_APP_TELEGRAM_BOT_TOKEN;
    const chatId = TELEGRAM_CHAT_ID || process.env.REACT_APP_TELEGRAM_CHAT_ID;

    if (!botToken || !chatId) return;

    try {
      await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chat_id: chatId,
          text: text,
          parse_mode: 'HTML'
        })
      });
    } catch (err) {
      console.error("Gagal mengirim notifikasi ke Telegram:", err);
    }
  }, []);

  // Check & Notify Transaksi Bermasalah
  const checkAndNotifyProblematicRows = useCallback((rows) => {
    if (!rows || rows.length === 0) return;

    const minusRows = rows.filter(item => {
      const hargaJual = Number(item.hargaJual) || 0;
      const hargaBeli = Number(item.hargaBeli) || 0;
      const laba = Number(item.laba) || 0;
      return hargaJual < 0 || hargaBeli < 0 || laba < 0;
    });

    const newProblematicRows = minusRows.filter(item => {
      if (!item.trxKey) return false;
      return !notifiedTrxKeysRef.current.has(item.trxKey);
    });

    if (newProblematicRows.length === 0) return;

    newProblematicRows.forEach(item => {
      notifiedTrxKeysRef.current.add(item.trxKey);
    });

    let message = `⚠️ <b>PERINGATAN TRANSAKSI MINUS DETEKSI</b> ⚠️\n`;
    message += `Ditemukan <b>${newProblematicRows.length}</b> transaksi dengan harga / laba bernilai minus!\n\n`;

    newProblematicRows.forEach((item, index) => {
      message += `<b>${index + 1}. Produk: ${item.produk || '-'}</b>\n`;
      message += `• Tgl Entri: ${item.tglEntri || '-'}\n`;
      message += `• Tujuan: ${item.tujuan || '-'}\n`;
      message += `• SN: ${item.sn || '-'}\n`;
      message += `• Status: ${item.status || '-'}\n`;
      message += `• Supplier: ${item.supplier || '-'}\n`;
      message += `• Harga Jual: Rp ${formatRupiah(item.hargaJual)}\n`;
      message += `• Harga Beli: Rp ${formatRupiah(item.hargaBeli)}\n`;
      message += `• Laba: Rp ${formatRupiah(item.laba)}\n`;
      message += `-----------------------------------\n`;
    });

    sendTelegramNotification(message);
  }, [formatRupiah, sendTelegramNotification]);

  const evaluateLaba = useCallback((labaVal) => {
    if (labaVal === null || labaVal === undefined) {
      return { isProblem: true, reason: "Laba Kosong / NA" };
    }
    const strVal = String(labaVal).trim().toUpperCase();
    if (strVal === "" || strVal === "NA" || strVal === "N/A" || strVal === "NULL" || strVal === "UNDEFINED") {
      return { isProblem: true, reason: "Laba N/A atau Kosong" };
    }
    const numVal = Number(String(labaVal).replace(/,/g, '').trim());
    if (isNaN(numVal)) {
      return { isProblem: true, reason: `Format Laba Tidak Valid (${strVal})` };
    }
    if (numVal < 0) {
      return { isProblem: true, reason: `Laba Negatif (${formatRupiah(numVal)})` };
    }
    return { isProblem: false, reason: "" };
  }, [formatRupiah]);

  const parseStatusFromRow = useCallback((item) => {
    let rawStatus = item['S'] || item['s'] || item.status || item.Status || item.STATUS || item.status_provider || item.statusProvider || item['Keterangan Status'] || "";

    if (!rawStatus) {
      const foundKey = Object.keys(item).find(k => k.toLowerCase() === 'status' || k.toLowerCase() === 'sts');
      if (foundKey) rawStatus = item[foundKey];
    }

    const kolomS = String(rawStatus).trim().toUpperCase();
    const jawabanProvider = String(item['N'] || item.jawabanProvider || item['Jawaban Provider'] || item.message || item.Message || "").trim().toUpperCase();

    const failKeywords = [
      "GAGAL", "REJECT", "CANCEL", "FAIL", "BATAL", "ERROR", 
      "SISA SALDO TIDAK CUKUP", "SALDO TIDAK CUKUP", "PIN SALAH", 
      "EXPIRED", "REFUND", "RJT", "DITOLAK", "TIBA-TIBA GAGAL", "INVALID"
    ];

    if (failKeywords.some(kw => kolomS.includes(kw)) || failKeywords.some(kw => jawabanProvider.includes(kw))) {
      return "Gagal";
    }

    const successKeywords = ["SUKSES", "SUCCESS", "OK", "BERHASIL"];
    if (successKeywords.some(kw => kolomS.includes(kw)) || successKeywords.some(kw => jawabanProvider.includes(kw))) {
      return "Sukses";
    }

    if (kolomS) {
      const str = String(kolomS).trim();
      return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
    }

    return "Sukses";
  }, []);

  const parseSupplierFromRow = useCallback((item) => {
    let raw = item.supplier || item.Supplier || item.SUPPLIER || item.vendor || item.Vendor || item['Nama Supplier'] || item['Provider'] || "";
    if (!raw && item['H']) raw = item['H'];

    let str = String(raw).trim();
    if (str && str.toUpperCase() !== "UNKNOWN" && str.toUpperCase() !== "") {
      return str.toUpperCase();
    }

    const combinedText = `${item['N'] || ''} ${item['D'] || ''} ${item['F'] || ''} ${item['S'] || ''} ${item.jawabanProvider || ''}`.toUpperCase();
    
    if (combinedText.includes("DIGIFLAZZ")) return "DIGIFLAZZ";
    if (combinedText.includes("DAS")) return "DAS";
    if (combinedText.includes("AMC")) return "AMC";
    if (combinedText.includes("HAO")) return "HAO";
    if (combinedText.includes("NEWBIEZ")) return "NEWBIEZ";
    if (combinedText.includes("OASIS")) return "OASIS";
    if (combinedText.includes("ANTUM")) return "ANTUM";

    return str ? str.toUpperCase() : "UNKNOWN";
  }, []);

  const parseExcelDate = useCallback((val) => {
    if (!val) return new Date();
    if (val instanceof Date && !isNaN(val)) return val;
    if (val && typeof val.toDate === 'function') return val.toDate();

    if (typeof val === 'number') {
      const parsedDate = XLSX.SSF.parse_date_code(val);
      if (parsedDate) {
        return new Date(
          parsedDate.y, 
          parsedDate.m - 1, 
          parsedDate.d, 
          parsedDate.H || 0, 
          parsedDate.M || 0, 
          parsedDate.S || 0
        );
      }
    }

    const str = String(val).trim();
    if (!str) return new Date();

    const regexFull = /^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})(?:\s+(\d{1,2})[:\.](\d{1,2})(?:[:\.](\d{1,2}))?)?$/;
    const match = str.match(regexFull);

    if (match) {
      let day = parseInt(match[1], 10);
      let month = parseInt(match[2], 10) - 1;
      let year = parseInt(match[3], 10);
      if (year < 100) year += 2000;

      let hour = match[4] ? parseInt(match[4], 10) : 0;
      let min = match[5] ? parseInt(match[5], 10) : 0;
      let sec = match[6] ? parseInt(match[6], 10) : 0;

      return new Date(year, month, day, hour, min, sec);
    }

    const stdDate = new Date(str);
    return isNaN(stdDate.getTime()) ? new Date() : stdDate;
  }, []);

  const formatOtomaxDate = useCallback((dateObj, manualTime = null) => {
    if (!(dateObj instanceof Date) || isNaN(dateObj)) return "-";
    const pad = (num) => num.toString().padStart(2, '0');
    const d = pad(dateObj.getDate());
    const m = pad(dateObj.getMonth() + 1);
    const y = dateObj.getFullYear().toString().slice(-2);
    
    let timeStr = "";
    if (manualTime) {
      timeStr = manualTime.replace(/:/g, '.');
    } else {
      const h = pad(dateObj.getHours());
      const min = pad(dateObj.getMinutes());
      const s = pad(dateObj.getSeconds());
      timeStr = `${h}.${min}.${s}`;
    }
    
    return `${d}/${m}/${y} ${timeStr}`;
  }, []);

  const parseOasisTglStatus = useCallback((jawabanProvider, entriDate) => {
    if (!jawabanProvider) return null;

    const oasisRegex = /\((\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})(\d{1,2}[:\.]\d{2}[:\.]\d{2})\)/i;
    const match = jawabanProvider.match(oasisRegex);

    if (match) {
      const yearFull = match[3];
      const year2Digit = yearFull.slice(-2);
      const rawTime = match[4];

      const timeParts = rawTime.split(/[:\.]/);
      if (timeParts.length === 3) {
        let hourStr = timeParts[0];
        let minStr = timeParts[1];
        let secStr = timeParts[2];

        if (hourStr.length > 2 || (parseInt(hourStr, 10) > 23 && hourStr.length === 2)) {
          hourStr = hourStr.slice(-1);
        }

        const formattedHour = hourStr.padStart(2, '0');
        const formattedMin = minStr.padStart(2, '0');
        const formattedSec = secStr.padStart(2, '0');

        const pad = (num) => num.toString().padStart(2, '0');
        const day = pad(entriDate.getDate());
        const month = pad(entriDate.getMonth() + 1);

        return `${day}/${month}/${year2Digit} ${formattedHour}.${formattedMin}.${formattedSec}`;
      }
    }

    return null;
  }, []);

  const processRowData = useCallback((item, index = 0) => {
    let rawEntriValue = item['A'] || item['Tgl Entri'] || item['tglEntri'] || item['Tanggal Entri'] || item['Tgl'] || item['Tanggal'] || item.rawDate;
    
    let entriDate = parseExcelDate(rawEntriValue);

    if (useCustomUploadDate && customUploadDate) {
      const [year, month, day] = customUploadDate.split('-');
      entriDate = new Date(
        parseInt(year),
        parseInt(month) - 1,
        parseInt(day),
        entriDate.getHours(),
        entriDate.getMinutes(),
        entriDate.getSeconds()
      );
    }

    const supplier = parseSupplierFromRow(item);
    const jawabanProvider = (item['N'] || item.jawabanProvider || item['Jawaban Provider'] || item.message || item.Message || "").toString();
    
    let finalTglStatus = "";
    
    if (supplier === "DIGIFLAZZ") {
      const statusDate = new Date(entriDate.getTime() + 10000);
      finalTglStatus = formatOtomaxDate(statusDate);
    } else if (supplier === "OASIS") {
      const parsedOasisDate = parseOasisTglStatus(jawabanProvider, entriDate);
      if (parsedOasisDate) {
        finalTglStatus = parsedOasisDate;
      } else {
        const timeMatch = jawabanProvider.match(/(\d{1,2}[:\.]\d{2}[:\.]\d{2})/);
        if (timeMatch) {
          const parts = timeMatch[0].split(/[:\.]/);
          let h = parts[0];
          if (h.length > 2) h = h.slice(-1);
          const formattedTime = `${h.padStart(2, '0')}:${parts[1]}:${parts[2]}`;
          finalTglStatus = formatOtomaxDate(entriDate, formattedTime);
        } else {
          const statusDate = new Date(entriDate.getTime() + 10000);
          finalTglStatus = formatOtomaxDate(statusDate);
        }
      }
    } else {
      const timeMatch = jawabanProvider.match(/(\d{2}[:\.]\d{2}[:\.]\d{2})/);
      if (timeMatch) {
        finalTglStatus = formatOtomaxDate(entriDate, timeMatch[0]);
      } else {
        const statusDate = new Date(entriDate.getTime() + 10000);
        finalTglStatus = formatOtomaxDate(statusDate);
      }
    }

    const finalStatus = parseStatusFromRow(item);
    const produk = (item['C'] || item.produk || item['Produk'] || item['Kode Produk'] || item['Nama Produk'] || "").toString().toUpperCase();
    const tujuan = (item['E'] || item.tujuan || item['Tujuan'] || item['No Tujuan'] || "").toString();
    const sn = (item['O'] || item.sn || item['SN'] || "").toString();
    const hargaJual = item['L'] !== undefined ? item['L'] : (item.hargaJual !== undefined ? item.hargaJual : (item['Harga Jual'] || 0));
    const hargaBeli = item['K'] !== undefined ? item['K'] : (item.hargaBeli !== undefined ? item.hargaBeli : (item['Harga Modal'] || 0));
    const laba = item['M'] !== undefined ? item['M'] : (item.laba !== undefined ? item.laba : (item['Profit'] || 0));
    
    const formattedTglEntri = formatOtomaxDate(entriDate);
    const trxKey = `${formattedTglEntri}_${produk}_${tujuan}_${sn}_${laba}`.replace(/\s+/g, '');
    const labaEval = evaluateLaba(laba);

    return {
      id: item.id || `manual_${index}_${Date.now()}`,
      rawDate: entriDate,
      tglEntri: formattedTglEntri,
      tglStatus: finalTglStatus,
      produk,
      tujuan,
      sn,
      status: finalStatus,
      hargaJual,
      hargaBeli,
      laba,
      supplier,
      jawabanProvider,
      trxKey,
      isProblematicLaba: labaEval.isProblem,
      problemReason: labaEval.reason
    };
  }, [useCustomUploadDate, customUploadDate, parseExcelDate, parseSupplierFromRow, formatOtomaxDate, parseOasisTglStatus, parseStatusFromRow, evaluateLaba]);

  // SINKRONISASI MASA BERLAKU DATA UPLOAD MANUAL
  useEffect(() => {
    const today = getTodayString();
    const savedUploadDate = sessionStorage.getItem('speed_excel_upload_date');

    if (savedUploadDate && savedUploadDate !== today) {
      sessionStorage.removeItem('speed_excel_upload_date');
      sessionStorage.removeItem('speed_excel_file_name');
      sessionStorage.removeItem('speed_excel_manual_data');
      setManualData([]);
      setIsManualUpload(false);
      setFileName('');
    } else {
      const storedFileName = sessionStorage.getItem('speed_excel_file_name');
      const storedManualData = sessionStorage.getItem('speed_excel_manual_data');
      if (storedFileName && storedManualData) {
        try {
          const parsed = JSON.parse(storedManualData);
          setFileName(storedFileName);
          setManualData(parsed);
          setIsManualUpload(true);
        } catch (e) {
          console.error("Gagal membaca session data Excel:", e);
        }
      }
    }
  }, [getTodayString]);

  // PROSES SINKRONISASI 1 HARI TERAKHIR (24 JAM TERAKHIR) DARI FIRESTORE
  useEffect(() => {
    let unsubscribe = () => {};
    setIsLoading(true);
    setErrorMessage('');

    // Mengambil rentang persis 24 jam terakhir dari waktu saat ini
    const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);
    const oneDayAgoTimestamp = Timestamp.fromDate(oneDayAgo);

    try {
      // 1. QUERY FILTER DIRECT: Hanya memuat data >= 1 hari terakhir
      const q = query(
        collection(db, "speed_log_data"),
        where("created_at", ">=", oneDayAgoTimestamp)
      );

      unsubscribe = onSnapshot(q, (snapshot) => {
        const fetchedData = snapshot.docs.map(docSnap => {
          return processRowData({ ...docSnap.data(), id: docSnap.id });
        });
        
        fetchedData.sort((a, b) => b.rawDate - a.rawDate);
        setDbData(fetchedData);
        checkAndNotifyProblematicRows(fetchedData);
        setIsLoading(false);
      }, (error) => {
        console.error("Firebase sync error:", error);
        setErrorMessage("Gagal menyinkronkan data dengan Firebase: " + error.message);
        setIsLoading(false);
      });

      // 2. BACKGROUND CLEANUP AUTOMATION: Otomatis hapus data yang lebih tua dari 24 jam
      const cleanupOldData = async () => {
        try {
          const oldDataQuery = query(
            collection(db, "speed_log_data"),
            where("created_at", "<", oneDayAgoTimestamp)
          );
          const oldDocsSnapshot = await getDocs(oldDataQuery);

          if (!oldDocsSnapshot.empty) {
            const BATCH_SIZE = 400;
            const docs = oldDocsSnapshot.docs;
            for (let i = 0; i < docs.length; i += BATCH_SIZE) {
              const batch = writeBatch(db);
              const chunk = docs.slice(i, i + BATCH_SIZE);
              chunk.forEach(docSnap => batch.delete(docSnap.ref));
              await batch.commit();
            }
            console.log(`[Background Cleanup] Berhasil menghapus ${docs.length} data lama (> 1 hari).`);
          }
        } catch (cleanupErr) {
          console.error("Background cleanup error:", cleanupErr);
        }
      };

      cleanupOldData();

    } catch (err) {
      console.error("Firestore Error:", err);
      setErrorMessage("Error koneksi database: " + err.message);
      setIsLoading(false);
    }

    return () => unsubscribe();
  }, [useCustomUploadDate, customUploadDate, processRowData, checkAndNotifyProblematicRows]);

  useEffect(() => {
    if (isManualUpload && manualData.length > 0) {
      setManualData(prev => prev.map((item, idx) => processRowData(item, idx)));
    }
  }, [useCustomUploadDate, customUploadDate, isManualUpload, processRowData]);

  useEffect(() => {
    if (isAutoFit) {
      setColumnWidths({
        tglEntri: 130, tglStatus: 130, produk: 90, tujuan: 140, sn: 180, status: 80,
        hargaJual: 100, hargaBeli: 100, laba: 90, supplier: 110, jawabanProvider: 300
      });
    } else {
      setColumnWidths(defaultWidths);
    }
  }, [isAutoFit, defaultWidths]);

  useEffect(() => {
    const onMouseMove = (e) => {
      if (!resizingColumn.current) return;
      const clientX = e.touches ? e.touches[0].pageX : e.pageX;
      const diff = clientX - startX.current;
      const newWidth = Math.max(20, startWidth.current + diff);
      setColumnWidths(prev => ({
        ...prev,
        [resizingColumn.current]: newWidth
      }));
    };
    
    const onMouseUp = () => { 
      resizingColumn.current = null; 
      document.body.style.cursor = 'default'; 
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
    window.addEventListener('touchmove', onMouseMove);
    window.addEventListener('touchend', onMouseUp);
    return () => {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
      window.removeEventListener('touchmove', onMouseMove);
      window.removeEventListener('touchend', onMouseUp);
    };
  }, []);

  const handleResizeStart = (e, colKey) => {
    const clientX = e.touches ? e.touches[0].pageX : e.pageX;
    resizingColumn.current = colKey;
    startX.current = clientX;
    startWidth.current = columnWidths[colKey];
    document.body.style.cursor = 'col-resize';
  };

  const handleReset = () => {
    setSearchTerm('');
    setStatusFilter('ALL');
    setDateFilter('');
    setIsAutoFit(false);
    setUseCustomUploadDate(false);
    setCustomUploadDate('');
    setFilterNaOnly(false);
    setColumnWidths(defaultWidths);
  };

  const handleResetDatabase = async () => {
    if (!window.confirm("Apakah Om yakin ingin MENGHAPUS PERMANEN seluruh database Log Speed dari Firebase?")) {
      return;
    }

    setIsLoading(true);
    try {
      const querySnapshot = await getDocs(collection(db, "speed_log_data"));
      const docs = querySnapshot.docs;
      
      const BATCH_SIZE = 400;
      for (let i = 0; i < docs.length; i += BATCH_SIZE) {
        const chunk = docs.slice(i, i + BATCH_SIZE);
        const batch = writeBatch(db);
        chunk.forEach(d => {
          batch.delete(d.ref);
        });
        await batch.commit();
      }

      setDbData([]);
      clearFile();
      alert("Database Firebase Log Speed berhasil di-reset total!");
    } catch (err) {
      console.error("Gagal melakukan reset database Firebase:", err);
      alert("Gagal reset database: " + err.message);
      setErrorMessage("Reset database gagal: " + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const clearFile = () => {
    setFileName('');
    setManualData([]);
    setIsManualUpload(false);
    sessionStorage.removeItem('speed_excel_upload_date');
    sessionStorage.removeItem('speed_excel_file_name');
    sessionStorage.removeItem('speed_excel_manual_data');
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleFileUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      setIsLoading(true);
      setErrorMessage('');
      setFileName(file.name);
      
      const reader = new FileReader();
      reader.onload = async (e) => {
        try {
          const dataArray = new Uint8Array(e.target.result);
          const workbook = XLSX.read(dataArray, { type: 'array', cellDates: true });
          const rawJson = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { 
            defval: "",
            header: "A" 
          });
          
          const firstCell = String(rawJson[0]?.['A'] || '').toLowerCase();
          const dataRows = (firstCell.includes('tgl') || firstCell.includes('entri') || firstCell.includes('tanggal')) ? rawJson.slice(1) : rawJson;
          
          const processedManualRows = dataRows.map((row, idx) => processRowData(row, idx));
          processedManualRows.sort((a, b) => b.rawDate - a.rawDate);

          setManualData(processedManualRows);
          setIsManualUpload(true);

          const todayStr = getTodayString();
          sessionStorage.setItem('speed_excel_upload_date', todayStr);
          sessionStorage.setItem('speed_excel_file_name', file.name);
          sessionStorage.setItem('speed_excel_manual_data', JSON.stringify(processedManualRows));

          checkAndNotifyProblematicRows(processedManualRows);
        } catch (err) { 
          console.error("Error processing excel:", err); 
          setErrorMessage("Gagal memproses file Excel: " + err.message);
        } finally {
          setIsLoading(false);
        }
      };
      reader.onerror = () => {
        setErrorMessage("Gagal membaca file dari disk.");
        setIsLoading(false);
      };
      reader.readAsArrayBuffer(file);
    }
  };

  const activeData = isManualUpload ? manualData : dbData;

  const filteredData = useMemo(() => {
    return activeData.filter(item => {
      const s = searchTerm.toLowerCase();
      const matchesSearch = item.tujuan.toLowerCase().includes(s) || 
                            item.produk.toLowerCase().includes(s) || 
                            item.sn.toLowerCase().includes(s);
      const matchesStatus = statusFilter === 'ALL' || item.status.toLowerCase() === statusFilter.toLowerCase();
      let matchesDate = true;
      if (dateFilter) {
        const itemDateStr = item.rawDate instanceof Date && !isNaN(item.rawDate) 
          ? item.rawDate.toISOString().split('T')[0] 
          : '';
        matchesDate = itemDateStr === dateFilter;
      }
      const isNA = item.sn.toUpperCase() === 'N/A' || item.sn.toUpperCase() === 'NA';
      const matchesNa = !filterNaOnly || isNA;

      return matchesSearch && matchesStatus && matchesDate && matchesNa;
    });
  }, [activeData, searchTerm, statusFilter, dateFilter, filterNaOnly]);

  const naRows = useMemo(() => {
    return filteredData.filter(item => item.sn.toUpperCase() === 'N/A' || item.sn.toUpperCase() === 'NA');
  }, [filteredData]);

  const copyToClipboard = () => {
    const text = naRows.map(item => 
      `Komplain SN N/A:\nTrx: ${item.produk}\nTujuan: ${item.tujuan}\nTgl: ${item.tglEntri}\nStatus: ${item.status}\nSN: ${item.sn}`
    ).join('\n\n');
    
    navigator.clipboard.writeText(text);
    alert('Format komplain berhasil disalin!');
  };

  const totalLaba = useMemo(() => {
    return filteredData.reduce((acc, curr) => acc + (Number(curr.laba) || 0), 0);
  }, [filteredData]);

  const minusLabaRows = useMemo(() => {
    return filteredData.filter(item => Number(item.laba) < 0);
  }, [filteredData]);

  const totalMinusLaba = useMemo(() => {
    return minusLabaRows.reduce((acc, curr) => acc + Number(curr.laba), 0);
  }, [minusLabaRows]);

  const HeaderCell = ({ title, colKey, hasArrow = false }) => (
    <th style={{ width: columnWidths[colKey] }} className="header-cell relative select-none">
      <div className="flex items-center justify-between w-full h-full px-1.5 py-0.5">
        <span className="truncate text-black font-normal text-[11px] leading-tight">
          {title}
        </span>
        {hasArrow && (
          <ChevronDown size={10} className="text-gray-600 shrink-0 ml-1" />
        )}
      </div>
      <div 
        onMouseDown={(e) => handleResizeStart(e, colKey)} 
        onTouchStart={(e) => handleResizeStart(e, colKey)}
        className="resizer" 
      />
    </th>
  );

  return (
    <div className="w-full max-w-full overflow-hidden p-1 md:p-0">
      
      {/* DASHBOARD HEADER */}
      <div className="grid grid-cols-1 gap-3 mb-3 font-sans">
        <div className="bg-white/90 backdrop-blur-md rounded-xl border border-red-200/80 p-3 shadow-sm hover:shadow-md transition-all duration-200">
          <div className="flex items-center justify-between pb-2 mb-2 border-b border-red-100">
            <div className="flex items-center gap-2">
              <div className="p-1.5 bg-red-100/80 rounded-lg text-red-600">
                <AlertTriangle size={15} />
              </div>
              <span className="font-semibold text-xs text-red-950 uppercase tracking-wider">
                Kontrol Kelainan Transaksi (24 Jam Terakhir)
              </span>
            </div>
            {naRows.length > 0 || minusLabaRows.length > 0 ? (
              <span className="flex h-2 w-2 relative">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2 w-2 bg-red-500"></span>
              </span>
            ) : (
              <span className="inline-flex items-center gap-1 text-[10px] text-emerald-600 font-medium bg-emerald-50 px-1.5 py-0.5 rounded-md">
                <CheckCircle2 size={10} /> Normal
              </span>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-2 text-xs">
            <div className="flex justify-between items-center py-1.5 px-2 rounded-lg bg-amber-50/50 hover:bg-amber-50 transition-colors">
              <span className="flex items-center gap-1.5 text-slate-600 font-medium">
                <HelpCircle size={13} className="text-amber-500" />
                Trx SN N/A:
              </span>
              <span className={`font-bold px-2 py-0.5 rounded-md text-[11px] ${
                naRows.length > 0 ? 'bg-amber-100 text-amber-800' : 'bg-slate-100 text-slate-600'
              }`}>
                {naRows.length} Transaksi
              </span>
            </div>

            <div className="flex justify-between items-center py-1.5 px-2 rounded-lg bg-red-50/50 hover:bg-red-50 transition-colors">
              <span className="flex items-center gap-1.5 text-slate-600 font-medium">
                <TrendingDown size={13} className="text-red-500" />
                Jml Laba Minus:
              </span>
              <span className={`font-bold px-2 py-0.5 rounded-md text-[11px] ${
                minusLabaRows.length > 0 ? 'bg-red-100 text-red-800' : 'bg-slate-100 text-slate-600'
              }`}>
                {minusLabaRows.length} Transaksi
              </span>
            </div>

            <div className="flex justify-between items-center py-1.5 px-2 rounded-lg bg-slate-50">
              <span className="text-slate-500 font-medium">Total Nominal Minus:</span>
              <span className="font-extrabold text-red-600 text-[12px]">
                Rp {formatRupiah(totalMinusLaba)}
              </span>
            </div>
          </div>
        </div>
      </div>

      <div className="flex flex-col bg-[#D4D0C8] font-['Tahoma',sans-serif] text-[11px] text-black border border-[#808080] rounded-sm overflow-hidden h-[85vh] md:h-[600px] shadow-sm relative">
        
        {/* Top Summary Bar */}
        <div className="bg-[#F0F0F0] border-b border-[#808080] px-2 py-1 flex items-center justify-between gap-4 text-[11px] font-bold select-none shrink-0">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-1">
              <span className="text-[#000080]">Total Transaksi (1 Hari Terakhir):</span>
              <span>{filteredData.length}</span>
            </div>
            <div className="flex items-center gap-1">
              <span className="text-[#000080]">Total Laba:</span>
              <span className="text-green-700">{formatRupiah(totalLaba)}</span>
            </div>
          </div>
          {isManualUpload && (
            <div className="bg-amber-200 text-amber-800 px-2 py-0.5 rounded text-[10px] font-semibold border border-amber-400 animate-pulse">
              Mode Manual (Sementar/Berlaku 1 Hari)
            </div>
          )}
        </div>

        {/* Toolbar Filter */}
        <div className="bg-[#F0F0F0] border-b border-[#808080] p-[4px] flex flex-wrap items-center gap-1 shrink-0 select-none">
          <div className="flex items-center bg-white border border-[#7F9DB9] px-1 h-[24px] md:h-[20px] flex-1 min-w-[120px]">
            <Calendar size={11} className="text-gray-400 mr-1" />
            <input type="date" className="outline-none text-[10px] w-full bg-transparent" value={dateFilter} onChange={(e) => setDateFilter(e.target.value)} />
          </div>
          
          <div className="flex items-center bg-white border border-[#7F9DB9] px-1 h-[24px] md:h-[20px] flex-1 min-w-[120px]">
            <SearchIcon size={11} className="text-gray-400 mr-1" />
            <input type="text" className="outline-none w-full text-[11px]" placeholder="Cari..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          </div>

          <div className="flex items-center gap-1 w-full md:w-auto">
            <select className="border border-[#7F9DB9] h-[24px] md:h-[20px] outline-none text-[11px] bg-white flex-1 md:w-20" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
              <option value="ALL">Semua</option>
              <option value="Sukses">Sukses</option>
              <option value="Gagal">Gagal</option>
            </select>

            {!fileName ? (
              <label className="flex items-center justify-center gap-1 px-2 h-[24px] md:h-[20px] bg-[#F0F0F0] border border-[#7F9DB9] hover:bg-[#E5E5E5] cursor-pointer text-[10px] flex-1 md:flex-none" title="Upload manual sementara (Berlaku 1 Hari)">
                <FileSpreadsheet size={11} className="text-green-700" />
                <span>Upload Manual</span>
                <input ref={fileInputRef} type="file" className="hidden" accept=".xlsx, .xls, .csv" onChange={handleFileUpload} />
              </label>
            ) : (
              <div className="flex items-center gap-1 bg-[#E1E1E1] border border-[#7F9DB9] px-2 h-[24px] md:h-[20px] text-[10px] flex-1 md:flex-none justify-between">
                <div className="flex items-center gap-1 overflow-hidden">
                  <FileSpreadsheet size={11} className="text-green-700" />
                  <span className="max-w-[60px] md:max-w-[80px] truncate uppercase text-black">{fileName}</span>
                </div>
                <button onClick={clearFile} className="ml-1 hover:text-red-600" title="Tutup file manual"><Trash2 size={11} /></button>
              </div>
            )}
          </div>

          <div className="flex items-center gap-1 border border-[#A0A0A0] bg-[#E1E1E1] p-[2px] h-[24px] md:h-[20px] rounded-sm">
            <label className="flex items-center gap-1 cursor-pointer text-[10px] font-semibold text-gray-700 px-1">
              <input 
                type="checkbox" 
                checked={useCustomUploadDate} 
                onChange={(e) => setUseCustomUploadDate(e.target.checked)}
                className="w-3 h-3"
              />
              <span>Ubah Tgl</span>
            </label>
            {useCustomUploadDate && (
              <input 
                type="date" 
                className="outline-none text-[10px] bg-white border border-[#7F9DB9] px-1 h-full font-sans" 
                value={customUploadDate} 
                onChange={(e) => setCustomUploadDate(e.target.value)} 
              />
            )}
          </div>

          <button
            onClick={() => setFilterNaOnly(prev => !prev)}
            className={`flex items-center gap-1 px-2 h-[24px] md:h-[20px] text-[10px] font-semibold border border-[#7F9DB9] rounded-sm transition-colors ${
              filterNaOnly ? 'bg-orange-600 text-white' : 'bg-[#E1E1E1] text-black hover:bg-[#D5D5D5]'
            }`}
          >
            <AlertTriangle size={11} className={filterNaOnly ? 'text-white' : 'text-orange-600'} />
            <span>Cek SN</span>
          </button>
        </div>

        {/* Tabel Utama */}
        <div className="flex-1 bg-white overflow-auto scrollbar-otomax touch-auto selection:bg-[#316AC5] selection:text-white relative">
          
          {isLoading && (
            <div className="absolute inset-0 bg-white/80 backdrop-blur-[1px] z-30 flex flex-col items-center justify-center gap-2">
              <Loader2 size={28} className="animate-spin text-[#000080]" />
              <span className="text-[11px] font-bold text-gray-700 font-sans tracking-wide">
                Memuat Data 1 Hari Terakhir...
              </span>
            </div>
          )}

          <div className="bg-white inline-block min-w-full">
            <table className="border-collapse table-fixed w-full" style={{ tableLayout: 'fixed' }}>
              <thead className="sticky top-0 z-20 select-none">
                <tr className="bg-[#F2F2F2]">
                  <th className="header-cell" style={{ width: '32px', textAlign: 'center' }}>#</th>
                  <HeaderCell title="Tgl. Entri" colKey="tglEntri" hasArrow={true} />
                  <HeaderCell title="Tgl. Status" colKey="tglStatus" />
                  <HeaderCell title="Produk" colKey="produk" />
                  <HeaderCell title="Tujuan" colKey="tujuan" />
                  <HeaderCell title="SN" colKey="sn" />
                  <HeaderCell title="Status" colKey="status" />
                  <HeaderCell title="Harga Jual" colKey="hargaJual" />
                  <HeaderCell title="Harga Beli" colKey="hargaBeli" />
                  <HeaderCell title="Laba" colKey="laba" />
                  <HeaderCell title="Supplier" colKey="supplier" />
                  <HeaderCell title="Jawaban Provider" colKey="jawabanProvider" />
                </tr>
              </thead>
              <tbody>
                {errorMessage && !isLoading && (
                  <tr>
                    <td colSpan={12} className="py-12 text-center text-red-600 bg-red-50/50">
                      <div className="flex flex-col items-center justify-center gap-1">
                        <AlertTriangle size={24} className="text-red-500 mb-1" />
                        <span className="font-bold text-xs">{errorMessage}</span>
                        <span className="text-[10px] text-gray-500">Periksa koneksi internet Anda.</span>
                      </div>
                    </td>
                  </tr>
                )}

                {!isLoading && !errorMessage && filteredData.length === 0 && (
                  <tr>
                    <td colSpan={12} className="py-12 text-center text-gray-500 bg-gray-50/30">
                      <div className="flex flex-col items-center justify-center gap-1">
                        <Inbox size={24} className="text-gray-400 mb-1" />
                        <span className="font-semibold text-xs text-gray-600">Tidak ada data transaksi 1 hari terakhir</span>
                        <span className="text-[10px] text-gray-400">Silakan unggah file terbaru via App.js atau manual button.</span>
                      </div>
                    </td>
                  </tr>
                )}

                {!isLoading && !errorMessage && filteredData.map((item, idx) => {
                  const isGagal = item.status.toLowerCase() === 'gagal';
                  const isNA = item.sn.toUpperCase() === 'N/A' || item.sn.toUpperCase() === 'NA';
                  const isLabaMinus = Number(item.laba) < 0;
                  
                  let rowBgClass = idx % 2 === 1 ? 'bg-[#F5F5F5]' : 'bg-white';
                  if (isGagal) {
                    rowBgClass = 'bg-[#FF4D4D] text-white'; 
                  } else if (isNA) {
                    rowBgClass = 'bg-[#FFF4CE]';
                  } else if (isLabaMinus) {
                    rowBgClass = 'bg-[#FFE6E6] text-red-900';
                  }
                  
                  return (
                    <tr key={item.id || idx} className={`row-otomax ${rowBgClass}`}>
                      <td className={`cell-otomax text-center select-none border-r-[#808080] text-[10px] ${isGagal ? 'bg-[#E60000] text-white' : 'bg-[#F0F0F0] text-gray-600'}`} style={{ width: '32px' }}>{idx + 1}</td>
                      <td className="cell-otomax px-1.5" style={{ width: columnWidths.tglEntri }}>{item.tglEntri}</td>
                      <td className="cell-otomax px-1.5" style={{ width: columnWidths.tglStatus }}>{item.tglStatus}</td>
                      <td className="cell-otomax px-1.5" style={{ width: columnWidths.produk }}>{item.produk}</td>
                      <td className="cell-otomax px-1.5" style={{ width: columnWidths.tujuan }}>{item.tujuan}</td>
                      <td className={`cell-otomax px-1.5 ${isNA && !isGagal ? 'font-bold text-orange-700' : ''}`} style={{ width: columnWidths.sn }}>{item.sn}</td>
                      <td className="cell-otomax px-1.5" style={{ width: columnWidths.status }}>{item.status}</td>
                      <td className="cell-otomax px-1.5 text-right" style={{ width: columnWidths.hargaJual }}>{formatRupiah(item.hargaJual)}</td>
                      <td className="cell-otomax px-1.5 text-right" style={{ width: columnWidths.hargaBeli }}>{formatRupiah(item.hargaBeli)}</td>
                      <td className={`cell-otomax px-1.5 text-right ${isLabaMinus ? 'font-bold text-red-600' : ''}`} style={{ width: columnWidths.laba }}>{formatRupiah(item.laba)}</td>
                      <td className="cell-otomax px-1.5" style={{ width: columnWidths.supplier }}>{item.supplier}</td>
                      <td className="cell-otomax px-1.5" style={{ width: columnWidths.jawabanProvider }}>{item.jawabanProvider}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        {!isLoading && naRows.length > 0 && (
          <div className="bg-[#FFF4CE] border-y border-[#808080] p-1 flex items-center justify-between animate-pulse select-none">
            <div className="flex items-center gap-2 text-[#856404] font-bold text-[10px]">
              <AlertTriangle size={14} className="text-orange-600" />
              <span>DITEMUKAN {naRows.length} DATA DENGAN SN: N/A</span>
            </div>
            <button 
              onClick={copyToClipboard}
              className="win-btn flex items-center gap-1 px-2 py-0.5 bg-[#E1E1E1]"
            >
              <Copy size={10} />
              SALIN KOMPLAIN
            </button>
          </div>
        )}

        {/* Footer Bar */}
        <div className="bg-[#D4D0C8] border-t border-[#808080] text-black px-1 h-[24px] md:h-[22px] flex items-center justify-between shrink-0 text-[10px] select-none">
          <div className="flex items-center gap-2">
              <label className="flex items-center gap-1 cursor-pointer hover:bg-white/50 px-1 py-0.5 border border-transparent active:border-[#808080]">
                <input 
                  type="checkbox" 
                  checked={isAutoFit} 
                  onChange={(e) => setIsAutoFit(e.target.checked)}
                  className="w-3 h-3"
                />
                <span className="leading-none">Resize</span>
              </label>
              <div className="w-[1px] h-3 bg-[#808080] mx-1" />
              <span className="opacity-70">Otomax Speed Log (Mode 1 Hari)</span>
          </div>
          
          <div className="flex items-center gap-1">
             <button onClick={handleReset} className="win-btn px-2">Reset Filter</button>
             <button 
               onClick={handleResetDatabase} 
               className="win-btn px-2 text-red-700 font-bold flex items-center gap-1 hover:bg-red-100"
               title="Hapus seluruh database permanen di Firebase"
             >
               <RotateCcw size={10} />
               Reset Database
             </button>
          </div>
        </div>

        {/* Dynamic Stylesheet */}
        <style>{`
          .scrollbar-otomax::-webkit-scrollbar { width: 14px; height: 14px; }
          .scrollbar-otomax::-webkit-scrollbar-track { background: #F0F0F0; border-left: 1px solid #C0C0C0; }
          .scrollbar-otomax::-webkit-scrollbar-thumb { 
            background: #D4D0C8; border: 1px solid #FFFFFF; 
            box-shadow: inset -1px -1px #808080, inset 1px 1px #FFF; 
          }
          .win-btn { 
            background: #D4D0C8; color: black; font-weight: normal; 
            height: 16px; border: 1px solid #FFF;
            box-shadow: inset 1px 1px #fff, 1px 1px #404040; line-height: 1; 
            font-size: 9px;
            cursor: pointer;
          }
          .win-btn:active {
            box-shadow: inset -1px -1px #fff, inset 1px 1px #404040;
          }
          .header-cell {
            border-right: 1px solid #A0A0A0;
            border-bottom: 1px solid #A0A0A0;
            border-top: 1px solid #A0A0A0;
            border-left: 1px solid #FFFFFF;
            height: 22px;
            background: #F2F2F2;
            font-weight: normal;
            text-align: left;
            font-family: 'Tahoma', sans-serif;
            overflow: hidden;
            box-sizing: border-box;
          }
          .resizer {
            position: absolute; 
            right: 0; 
            top: 0; 
            bottom: 0; 
            width: 5px;
            cursor: col-resize; 
            z-index: 10;
          }
          .resizer:hover {
            background-color: #000080;
            opacity: 0.3;
          }
          .row-otomax { height: 20px; transition: none; display: table-row; }
          
          .cell-otomax {
              border-right: 1px solid #D0D0D0;
              border-bottom: 1px solid #D0D0D0;
              height: 20px;
              font-family: 'Tahoma', sans-serif;
              font-size: 11px;
              color: inherit;
              white-space: nowrap;
              overflow: hidden;
              text-overflow: clip;
              display: table-cell;
              vertical-align: middle;
              user-select: text;
          }

          @media (hover: hover) {
            .row-otomax:hover { 
              background-color: #E8F2FF !important;
              color: black !important;
            }
          }
          
          @media (max-width: 640px) {
            .win-btn { height: 18px; padding: 0 6px; }
          }
        `}</style>
      </div>
    </div>
  );
};

export default LogSpeedPanel;